\begin{definition}[$(\alpha, b)$-balanced sparse cut algorithm] \label{def:BalancedSparseCut}
	Let $\alpha \geq 1$, $b \leq 1$ be some parameters. An algorithm is an $(\alpha, b)$-balanced sparest cut algorithm if, given a parameter $\phi \in [0, 1]$ and access to some information about the graph $G$, it either
	\begin{itemize}\item declares that $G$ is a $\phi$-expander\\\\
		or
		\item returns a cut $S$ such that $\Phi_{G}(S)\le \alpha \cdot \phi$, and for
		every cut $S'$ in $G$ where $\Phi_{G}(S')\le\phi$, $\bal_{G}(S) \ge b \cdot \bal_{G}(S')$.
	\end{itemize}
\end{definition}

\begin{figure}[!h]
 \fbox{\begin{minipage}{43.5em}
\begin{multicols}{2}
\begin{flushleft}
	{\small
\begin{itemize}
	\item $\alpha, b$ --- balanced sparse cut parameters (\Cref{def:BalancedSparseCut})
   	\item $\eps$ --- desired fraction of inter-cluster edges.
	\item $k \in \mathbb{N}$	--- quality parameter.
	\item $\mathrm{O}$ --- upper bound on $\vol(G)$.
