\begin{algorithm}[!h]
	\caption{\texttt{Low-depth-expander-decomposition}$\left(C,\epsilon,k, i\right)$}\label{alg:streaming_ed}
	\DontPrintSemicolon
	\SetKwInOut{Input}{input}\SetKwInOut{Output}{output}
	\Input{cluster $C\subseteq V$, parameter bounding the number of outer-cluster edges $\eps$, quality parameter $k$, counter for the depth of the recursion $i$.}
	\Output{expander decomposition of $C$.}
	\SetKwFunction{Lded}{Low-depth-expander-decomposition}
	\SetKwFunction{Ubcd}{Unbalanced-cluster-decomposition}
Use an $(\alpha,b)$-balanced sparse cut algorithm (\Cref{def:BalancedSparseCut}) with the sparsifier $G_{\psi_0,\delta}^i\{C\}$ and parameter $\phi = \phi_0$
\tcp*{$G_{\psi_0,\delta}^{i}$ is global knowledge, recall $\psi_0=\delta\cdot \phi_0$}
	\If{it declares that $C$ is $\phi_0$-expander}
	{\Return{$C$}}
	\Else{
		Let $S$ be the returned $\alpha \cdot \phi_0$-sparse cut\;
		\If{$\text{Vol}_{G}(S)\ge\frac{\eps\cdot b}{4}\cdot\text{Vol}_{G}(C)$}{
			\Return  \Lded{$S,\epsilon,k, i+1$} $\cup$
			\Lded{$C\setminus S,\epsilon, k,i+1$} \label{line:returnBalanced}\;
		}
		\Else{
			\Return \Ubcd{$C, \epsilon, k$}\;
		}
	}
\end{algorithm}

\begin{algorithm}[!h]
	\caption{\texttt{Unbalanced-cluster-decomposition}$(C_0, \epsilon, k)$}\label{alg:decomp_unbal}
	\DontPrintSemicolon
	\SetKwInOut{Input}{input}\SetKwInOut{Output}{output}
	\Input{Cluster $C_0\subseteq V$ which does not contain a balanced sparse cut, parameter bounding the number of outer-cluster edges $\eps$, quality parameter $k$.}
	\Output{Expander decomposition of $C_0$.}
	$\phi_1 \gets \frac{\epsilon}{2\log(\vol(G))\alpha^2}$\;
	$C \gets C_0$, $\tau \gets  (\epsilon \cdot \vol_{G}(C))^{1/k}$, $m_1 \gets \epsilon \cdot \vol_{G}(C)$\;
	\For{$j=1$ to $\infty$}{\For{$h=1$ to $\infty$}{$G_{\psi_j,\delta}^{C}\leftarrow G_{\psi_j,\delta}^{h }\{C\}$\tcp*{$G_{\psi_j,\delta}^{h}$ is global knowledge}
			Run an $(\alpha,b)$-balanced sparse cut algorithm (\Cref{def:BalancedSparseCut}) on the sparsifier $G_{\psi_j,\delta}^{C}$ and parameter $\phi = \phi_j$\;
\If{it declares that $C$ is $\phi_j$-expander}{
				\Return $C$, $\left\{ u\right\} _{u\in {C_0 \setminus C}}$ \label{line:ubcd_return}
				\tcp*{The only return point of this algorithm}
			}
			\Else{
				Let $S$ be the returned $\alpha \cdot  \phi_j$-sparse cut \label{line:ubcd_cut}\;
				\If{$\text{Vol}_{G}(S)\ge \frac{b}{2} m_j$}{
					$C \gets C \setminus S$
				}
				\Else {
					\label{line:ubcd_break}
					\textbf{break} inner loop, \textbf{goto} \cref{line:updateJ}\;}
			}
}
		$m_{j + 1} \gets m_j / \tau$, $\phi_{j + 1} \gets \phi_j / \alpha $\label{line:updateJ}\;
	}
\end{algorithm}

$\eps$ is required to be in $(0,\frac14)$. $k \in \mathbb{N}$ is a parameter regulating the tradeoff between the required space (number of sparsifiers we will be using) and the quality of the expander decomposition. Let $\delta \leq 1/16$ be the parameter of power cut sparsifier, $\alpha, b$ be the balanced sparse cut lemma parameters.
Fix $\phi_0=\frac{\epsilon}{2\log(\vol(G)) \alpha}$ and $\phi_{j} = \phi_{j - 1} / \alpha$ for $j \in \mathbb{N}$. Similarly, let $\psi_j=\delta \cdot \phi_j$ for $j \in \mathbb{N} \cup \{0\}$.
Let $\mathrm{T} = \lceil (\eps \cdot \vol_G(G))^{1/k} \rceil$.

\begin{lemma}
	\label{lem:SparseCutSum}
	Let $G=(V, E)$ be an arbitrary graph, and let $\phi \in [0, 1]$. Consider a pair of cuts: $S_1$ which is $\phi$-sparse in $G$, and $S_2$ which is   $\phi$-sparse in $G\setminus S_1$. 
	Then, if $\vol_G(S_1 \cup S_2) \leq \frac12\vol_G(V)$, the cut $S_1 \cup S_2$ is $\phi$-sparse in $G$.
\end{lemma}

For a fixed invocation of \Cref{alg:decomp_unbal}, we denote by $k'$ the number of the outer loop iteration at the time where the algorithm returns (i.e. the value of the index $j$ in \cref{line:ubcd_return}). Let $C_j$ be the value of the variable $C$ at the end of iteration $j$ of the outer loop. In particular, $C_{k'}$ is the returned non-singleton cluster in \cref{line:ubcd_return}.


